/* --- runtime --- */
/* Dart_InitializeApiDL — pass NativeApi.initializeApiDLData once at startup. */
void throne_init_dart_api(void * api);

/* Receives unsolicited events (logs, ...) as JSON strings via Dart_PostCObject. */
void throne_attach_message_port(int64_t port);

/* Release a string returned by any throne_* export. */
void throne_free(char * p);

/* Error of the last failing throne_* call (thread-safe); empty when none. Read and clear after calls whose Java form declares `throws`. */
char * throne_last_error(void);

/* Drop a handle returned by a constructor or an object-returning call. */
void throne_handle_release(int64_t h);

/* Live/created/released handle counters as JSON: FFI lifetime diagnostics. */
char * throne_handle_stats(void);

/* All status fields in one JSON object; creates no handle and pushes a "status" event. */
char * throne_status_snapshot(int64_t handle);

/* Feed the VpnService fd and the TunInterface token to the kernel before Start. */
int32_t throne_start_tun(int32_t fd, void * tun);

/* Stop the tun started by throne_start_tun. */
void throne_stop_tun(void);

/* 0 = resume, 1 = suspend, 2 = doze-suspend. */
void throne_suspend(int32_t suspended);

/* Filled by JNI_OnLoad in core.cpp; Go calls the platform through these. */
void throne_register_callbacks(throne_callbacks_t * table);

/* Tun inbound section of the core config as JSON, for VpnService.Builder (establish() → fd → throne_start_tun). */
char * throne_getAndroidVpnOptions(char * coreConfig);

/* A TunOptions handle as JSON {mtu,inet4Address[],autoRoute,dnsMode,...} — the open_tun callback reads the fields it needs to build VpnService.Builder without the gobind TunOptions type. */
char * throne_TunOptions_toJSON(int64_t options);

